bloops.css:
html[data-theme=dark].bgaext_bright .bga-cards_card > .bga-cards_card-sides > .bga-cards_card-side {
  filter: var(--ext-bright);
}
html[data-theme=dark].bgaext_dark .blo-player {
  outline: 1px solid var(--dark-40);
}
html[data-theme=dark].bgaext_dark .blo-card-cell {
  background-color: var(--dark-10);
  border-color: var(--dark-40);
}
html[data-theme=dark].bgaext_dark #blo-discard {
  background-color: var(--dark-10);
  border-color: var(--dark-40);
  color: var(--light-70);
}

daydream.css:
.bgext_avatar path {
  fill: currentColor;
  stroke: currentColor;
  stroke-width: 38.88;
}
html[data-theme=dark].bgaext_bright .board-ABC:before {
  content: "";
  background: var(--ext-alpha);
  position: absolute;
  width: 100%;
  height: 100%;
  top: 0px;
  left: 0px;
  pointer-events: none;
}
html[data-theme=dark].bgaext_bright .custom-background-left-A,
html[data-theme=dark].bgaext_bright .custom-background-left-D,
html[data-theme=dark].bgaext_bright .custom-background-right-A,
html[data-theme=dark].bgaext_bright .custom-background-right-D {
  filter: var(--ext-bright);
}
html[data-theme=dark].bgaext_dark body {
  background: none;
}
html[data-theme=dark].bgaext_dark .board-title {
  background: var(--dark-20);
}
html[data-theme=dark].bgaext_dark .custom-button.selected,
html[data-theme=dark].bgaext_dark .custom-button:hover {
  border-color: var(--blue-80);
}

rivals.css:
html[data-theme=dark].bgaext_bright .bga-cards_card > .bga-cards_card-sides > .bga-cards_card-side,
html[data-theme=dark].bgaext_bright .riv_ashak {
  filter: var(--ext-bright);
}
html[data-theme=dark].bgaext_bright .riv_tile {
  filter: var(--ext-bright) drop-shadow(0 0 1px);
}
html[data-theme=dark].bgaext_bright .riv_ashak-board:before {
  content: "";
  background: var(--ext-alpha);
  position: absolute;
  width: 100%;
  height: 100%;
  top: 0px;
  left: 0px;
  pointer-events: none;
  border-radius: 10px;
}
html[data-theme=dark].bgaext_dark #overall-content,
html[data-theme=dark].bgaext_dark #riv-ashak-draft-info {
  color: var(--light-80);
}
html[data-theme=dark].bgaext_dark .riv_floating-selection,
html[data-theme=dark].bgaext_dark .riv_ashak-board-temporary-effects:empty {
  background: var(--dark-back);
}
html[data-theme=dark].bgaext_dark .bgabutton_gray:after {
  border: none;
}
html[data-theme=dark].bgaext_dark #riv-toggle-hand button {
  background: var(--dark-10);
}
html[data-theme=dark].bgaext_dark .riv_pp-wrapper {
  border-color: var(--dark-40);
}

stackfive.css:
html[data-theme=dark].bgaext_bright .mf_item_back,
html[data-theme=dark].bgaext_bright .mf_item_front,
html[data-theme=dark].bgaext_bright .mf_log_card > div {
  filter: var(--ext-bright);
}
html[data-theme=dark].bgaext_dark #page-title,
html[data-theme=dark].bgaext_dark #maingameview_menuheader,
html[data-theme=dark].bgaext_dark #maingameview_menufooter {
  border: 1px solid var(--dark-40);
}
html[data-theme=dark].bgaext_dark #maingameview_menuheader {
  border-top: none;
  top: -1px;
}
html[data-theme=dark].bgaext_dark .mf_popup_content {
  background-color: var(--dark-20);
}
html[data-theme=dark].bgaext_dark .mf_help {
  color: var(--light-80);
}
html[data-theme=dark].bgaext_dark .mf_zone {
  outline: 1px solid var(--light-50);
}

winter.css:
html[data-theme=dark].bgaext_dark.winter_background_blue #winter_overall_background {
  filter: brightness(0.35) saturate(1.3);
}
html[data-theme=dark].bgaext_bright .winter_card,
html[data-theme=dark].bgaext_bright .winter_card_back,
html[data-theme=dark].bgaext_bright .winter_card_spot {
  filter: var(--ext-bright);
}
html[data-theme=dark].bgaext_dark #player_board_config {
  background-color: var(--dark-20);
}
html[data-theme=dark].bgaext_dark #player_config #turn_counter_wrapper {
  background: none;
  color: var(--light-80);
}
html[data-theme=dark].bgaext_dark #winter_map_container {
  outline-color: var(--light-50);
}
